async () => {
const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const section = async (title) => {
  const trig = [...document.querySelectorAll('button')].find((b) => txt(b.innerText) === title && b.hasAttribute('aria-expanded'));
  if (!trig) return { err: 'NO TRIGGER ' + title };
  if (trig.getAttribute('aria-expanded') !== 'true') { trig.scrollIntoView({ block: 'center' }); trig.click(); await wait(800); }
  const panel = document.getElementById(trig.getAttribute('aria-controls') || '');
  const scope = panel || trig.closest('h3,[role=heading]')?.parentElement;
  return { trig, scope, expanded: trig.getAttribute('aria-expanded') };
};
const swatches = (scope) => {
  const names = [...scope.querySelectorAll('button[class*=selectButton]')].map((b) => txt(b.getAttribute('aria-label')));
  const groups = [...scope.querySelectorAll('[class*=groupTitle]')].map((e) => txt(e.innerText));
  return { count: names.length, groups, swatches: names.sort() };
};
const price = async (scope, pick) => {
  const btn = [...scope.querySelectorAll('button[aria-haspopup=listbox]')]
    .find((b) => /^(Price|Standard \$|Classic \$\$|Specialty \$\$\$|Exclusive \$\$\$\$|Show all)$/.test(txt(b.innerText)));
  if (!btn) return { err: 'NO PRICE BUTTON' };
  const was = txt(btn.innerText);
  btn.click(); await wait(600);
  const lb = [...document.querySelectorAll('[role=listbox][aria-label=Price]')].pop();
  if (!lb) return { err: 'NO LISTBOX', was };
  const opts = [...lb.querySelectorAll('[role=option]')];
  const label = (o) => txt(o.querySelector('span')?.innerText || o.innerText);
  const offered = opts.map(label);
  if (!pick) {
    lb.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); await wait(300);
    if (document.querySelector('[role=listbox][aria-label=Price]')) { btn.click(); await wait(300); }
    return { was, offered };
  }
  const o = opts.find((x) => label(x) === pick);
  if (!o) return { err: 'NO OPTION ' + pick, was, offered };
  (o.querySelector('button') || o).click(); await wait(800);
  return { was, offered, picked: pick };
};
const dialog = () => [...document.querySelectorAll('[role=dialog]')].pop();
const s = await section('Vessel Sink Style'); if (s.err) return s; const b = s.scope.querySelector('button[aria-label="Plaza"]'); if (!b) return { err: 'NO PLAZA', ...swatches(s.scope) }; b.scrollIntoView({ block: 'center' }); b.click(); await wait(4000); return 'picked Plaza';}

